-		    authenc_keys.enckeylen != AES_KEYSIZE_192 &&
-		    authenc_keys.enckeylen != AES_KEYSIZE_256)
-			return -EINVAL;
-		if (authenc_keys.enckeylen == AES_KEYSIZE_192)
-			ctx->need_fallback = true;
-	}
