-	ctx->enc_keylen = authenc_keys.enckeylen;
-	ctx->auth_keylen = authenc_keys.authkeylen;
-
-	memcpy(ctx->enc_key, authenc_keys.enckey, authenc_keys.enckeylen);
-
-	memcpy_and_pad(ctx->auth_key, sizeof(ctx->auth_key),
