-static inline void qce_write_array(struct qce_device *qce, u32 offset,
-				   const u32 *val, unsigned int len)
-{
-	int i;
-
-	for (i = 0; i < len; i++)
-		qce_write(qce, offset + i * sizeof(u32), val[i]);
