-		ret = -ENOMEM;
-		goto err_free_ahash;
-	}
-
-	crypto_init_wait(&wait);
-	ahash_request_set_callback(req, CRYPTO_TFM_REQ_MAY_BACKLOG,
-				   crypto_req_done, &wait);
-	crypto_ahash_clear_flags(ahash_tfm, ~0);
