-	}
-
-	memcpy(buf, key, keylen);
-	sg_init_one(&sg, buf, keylen);
-	ahash_request_set_crypt(req, &sg, ctx->authkey, keylen);
-
-	ret = crypto_wait_req(crypto_ahash_digest(req), &wait);
-
-	kfree(buf);
-err_free_req:
-	ahash_request_free(req);
-err_free_ahash:
-	crypto_free_ahash(ahash_tfm);
-	return ret;
-}
